// Build a Markdown brief from the sources that survived the filter.
// Everything here is plain string work - no credential, no request.
//
// Field names come from the DuckDuckGo node's page-metadata output, which
// prefixes them: pageContent, pageSiteName, pagePublished.
//
// A title, a site name and an extract are text from a web page, and the brief may be
// rendered as HTML further on (an email, a Markdown viewer). So page text is made inert
// first: one line, "<" and ">" as entities, "[", "]" and "\" escaped so that it cannot
// become markup or a link, and nothing that could start a heading or a list at the start
// of a line. An address becomes a link only when it is http(s).

const sources = $input.first().json.data || [];
const query = $('Search and extract article text').params.query || 'the search query';

// Zero-width spaces, direction overrides and Unicode tag characters can hide what is shown; the
// joiners and direction marks some scripts need (a zero-width non-joiner, for one) are text and stay.
const oneLine = (s) => String(s == null ? '' : s)
  .split(String.fromCharCode(0)).join('')
  .replace(/[\u200b\u202a-\u202e\u2060-\u206f\ufeff]/g, '')
  .replace(/[\u{e0000}-\u{e007f}]/gu, '')
  .replace(/[\u0001-\u001f\u007f-\u009f]/g, ' ')
  .replace(/\s+/g, ' ').trim();
const clip = (s, max) => (s.length > max ? s.slice(0, max).replace(/[\ud800-\udbff]$/, '') + '…' : s);
const inert = (s) => s.replace(/[<>]/g, (c) => (c === '<' ? '&lt;' : '&gt;')).replace(/[\\\[\]`]/g, (c) => '\\' + c);
// The start of a line of page text - the site line, and the extract after "> " - must not read as a
// heading, a list item or a rule.
const lineStart = (s) => s.replace(/^(\d+)([.)])(?=\s|$)/, '$1\\$2').replace(/^[#+*\-=~|_`]/, '\\$&');
// A link target is cut off by ")", a quote mark ends the attribute or starts a title, and a control
// character can be taken for a line break: encode them all.
const href = (u) => {
  const t = String(u).split(String.fromCharCode(0)).join('').trim();
  return /^https?:\/\//i.test(t)
    ? t.replace(/[\s\u0001-\u001f\u007f-\u009f()"'<>\[\]\\`]/g, (c) => (c === '(' ? '%28' : c === ')' ? '%29' : c === "'" ? '%27' : encodeURIComponent(c)))
    : null;
};

const lines = [
  '# Research brief',
  '',
  `**Question:** ${inert(clip(oneLine(query), 300))}`,
  `**Sources:** ${sources.length}`,
  `**Built:** ${new Date().toISOString().slice(0, 10)}`,
  '',
];

sources.forEach((s, i) => {
  const site = clip(oneLine(s.pageSiteName || s.hostname), 100);
  const date = s.pagePublished ? oneLine(String(s.pagePublished).slice(0, 10)) : '';
  const meta = lineStart(inert([site, date].filter(Boolean).join(' · ')));
  // A "#" at the end of a heading is read as its closing mark ("Learn C#" would lose it).
  const title = (inert(clip(oneLine(s.title), 200)) || inert(site) || 'Untitled').replace(/#+$/, (m) => m.replace(/#/g, '\\#'));
  const extract = clip(oneLine(s.pageContent), 700);
  const link = href(s.url);

  lines.push(`## ${i + 1}. ${title}`);
  lines.push(meta);
  lines.push('');
  lines.push(`> ${lineStart(inert(extract))}`);
  lines.push('');
  if (link) {
    lines.push(`[Read in full](${link})`);
    lines.push('');
  }
});

return [{ json: { query, sourceCount: sources.length, brief: lines.join('\n') } }];
